insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('tr', 'İşBul KKTC nedir?', 'İşBul KKTC, Kuzey Kıbrıs Türk Cumhuriyeti için geliştirilen bir iş ve kariyer platformudur. İş arayanlar ilanları arar ve başvurur; işverenler ilan yayınlar ve başvuruları yönetir.', 0, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('tr', 'Hangi bölgelerde hizmet veriyor?', 'Platform, Kuzey Kıbrıs''ın altı ilçesini kapsar: Lefkoşa, Gazimağusa, Girne, Güzelyurt, İskele ve Lefke.', 1, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('tr', 'İlan yayınlamak ve başvurmak ücretli mi?', 'İş arayanlar için ilan arama ve başvuru ücretsizdir. İşverenler ilan paketlerini inceler; ödeme web sitesinde alınmaz, IBAN ve ödeme talimatı paket görüşmesi sonrası e-posta veya WhatsApp gibi kanallardan özel olarak iletilir.', 2, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('tr', 'Şirket rehberindeki kayıtlar doğrulanmış mı?', 'Şirket rehberi, sağlanan kaynaklardaki kayıtları aramaya açar; listelenmek şirketin İşBul KKTC tarafından doğrulandığı anlamına gelmez.', 3, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('tr', 'İşBul KKTC''ye nasıl ulaşabilirim?', 'E-posta (info@isbulkktc.com), telefon veya WhatsApp üzerinden ulaşabilirsiniz. Destek kanalları sitenin alt bilgisinde ve iletişim sayfasında listelenir.', 4, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('tr', 'Platform hangi dilleri destekliyor?', 'Arayüz altı dilde sunulur: Türkçe, İngilizce, Rusça, Yunanca, Farsça ve Almanca.', 5, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('en', 'What is İşBul KKTC?', 'İşBul KKTC is a jobs and careers platform built for the Turkish Republic of Northern Cyprus. Job seekers search listings and apply; employers publish vacancies and manage applications.', 0, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('en', 'Which areas does it cover?', 'The platform covers the six districts of Northern Cyprus: Nicosia, Famagusta, Kyrenia, Morphou, Trikomo and Lefka.', 1, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('en', 'Does it cost anything to post or apply?', 'Searching and applying is free for job seekers. Employers review job packages; payment is not collected on the website — IBAN details and payment instructions are shared privately by email or WhatsApp after discussing the package.', 2, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('en', 'Are the directory listings verified?', 'The company directory makes records from supplied source files searchable; a listing does not mean İşBul KKTC has verified that company.', 3, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('en', 'How can I contact İşBul KKTC?', 'By email (info@isbulkktc.com), phone or WhatsApp. The support channels are listed in the site footer and on the contact page.', 4, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('en', 'Which languages does the platform support?', 'The interface is available in six languages: Turkish, English, Russian, Greek, Persian and German.', 5, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('ru', 'Что такое İşBul KKTC?', 'İşBul KKTC — платформа для поиска работы и построения карьеры в Турецкой Республике Северного Кипра. Соискатели ищут вакансии и откликаются; работодатели публикуют вакансии и управляют откликами.', 0, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('ru', 'Какие районы охватывает платформа?', 'Платформа охватывает шесть районов Северного Кипра: Никосия, Фамагуста, Кирения, Морфу, Трикомо и Лефка.', 1, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('ru', 'Платное ли размещение вакансий или отклики?', 'Поиск и отклики для соискателей бесплатны. Работодатели изучают пакеты вакансий; оплата не взимается на сайте — реквизиты и инструкции передаются лично по электронной почте или WhatsApp после обсуждения пакета.', 2, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('ru', 'Проверены ли записи в каталоге?', 'Каталог позволяет искать записи из предоставленных источников; наличие записи не означает, что İşBul KKTC проверил компанию.', 3, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('ru', 'Как связаться с İşBul KKTC?', 'По электронной почте (info@isbulkktc.com), телефону или WhatsApp. Каналы поддержки указаны в подвале сайта и на странице контактов.', 4, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('ru', 'Какие языки поддерживает платформа?', 'Интерфейс доступен на шести языках: турецком, английском, русском, греческом, персидском и немецком.', 5, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('el', 'Τι είναι το İşBul KKTC;', 'Το İşBul KKTC είναι μια πλατφόρμα εργασίας και καριέρας για την Τουρκική Δημοκρατία της Βόρειας Κύπρου. Οι αναζητούντες εργασία αναζητούν αγγελίες και υποβάλλουν αιτήσεις· οι εργοδότες δημοσιεύουν θέσεις και διαχειρίζονται τις αιτήσεις.', 0, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('el', 'Ποιες περιοχές καλύπτει;', 'Η πλατφόρμα καλύπτει τις έξι επαρχίες της Βόρειας Κύπρου: Λευκωσία, Αμμόχωστο, Κερύνεια, Μόρφου, Τρίκωμο και Λεύκα.', 1, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('el', 'Υπάρχει χρέωση για δημοσίευση ή αίτηση;', 'Η αναζήτηση και η υποβολή αίτησης είναι δωρεάν για τους αναζητούντες εργασία. Οι εργοδότες εξετάζουν τα πακέτα αγγελιών· η πληρωμή δεν γίνεται στον ιστότοπο — τα στοιχεία IBAN και οι οδηγίες κοινοποιούνται ιδιωτικά μέσω email ή WhatsApp μετά τη συζήτηση του πακέτου.', 2, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('el', 'Οι εγγραφές του καταλόγου είναι επαληθευμένες;', 'Ο κατάλογος εταιρειών επιτρέπει την αναζήτηση εγγραφών από παρεχόμενες πηγές· μια εγγραφή δεν σημαίνει ότι το İşBul KKTC έχει επαληθεύσει την εταιρεία.', 3, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('el', 'Πώς μπορώ να επικοινωνήσω με το İşBul KKTC;', 'Μέσω email (info@isbulkktc.com), τηλεφώνου ή WhatsApp. Τα κανάλια υποστήριξης αναφέρονται στο υποσέλιδο του ιστοτόπου και στη σελίδα επικοινωνίας.', 4, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('el', 'Ποιες γλώσσες υποστηρίζει η πλατφόρμα;', 'Η διεπαφή είναι διαθέσιμη σε έξι γλώσσες: τουρκικά, αγγλικά, ρωσικά, ελληνικά, περσικά και γερμανικά.', 5, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('fa', 'İşBul KKTC چیست؟', 'İşBul KKTC یک پلتفرم کاریابی و مسیر شغلی است که برای جمهوری ترک قبرس شمالی ساخته شده است. کارجویان آگهی‌ها را جست‌وجو و درخواست می‌دهند؛ کارفرمایان آگهی منتشر می‌کنند و درخواست‌ها را مدیریت می‌کنند.', 0, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('fa', 'این پلتفرم کدام مناطق را پوشش می‌دهد؟', 'این پلتفرم شش شهرستان قبرس شمالی را پوشش می‌دهد: لفکوشا، غازی‌ماغوسا، گیرنه، گوزلیورت، ایسکله و لفکه.', 1, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('fa', 'ثبت آگهی یا درخواست هزینه دارد؟', 'جست‌وجو و درخواست برای کارجویان رایگان است. کارفرمایان بسته‌های آگهی را بررسی می‌کنند؛ پرداخت در وب‌سایت انجام نمی‌شود و اطلاعات IBAN پس از گفتگو درباره بسته، از طریق ایمیل یا واتساپ به‌صورت خصوصی ارسال می‌شود.', 2, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('fa', 'اطلاعات فهرست شرکت‌ها تأیید شده است؟', 'فهرست شرکت‌ها امکان جست‌وجوی اطلاعات فایل‌های منبع را می‌دهد؛ ثبت یک شرکت به‌معنای تأیید آن توسط İşBul KKTC نیست.', 3, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('fa', 'چگونه می‌توانم با İşBul KKTC تماس بگیرم؟', 'از طریق ایمیل (info@isbulkktc.com)، تلفن یا واتساپ. کانال‌های پشتیبانی در پاورقی وب‌سایت و صفحه تماس فهرست شده‌اند.', 4, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('fa', 'پلتفرم از چه زبان‌هایی پشتیبانی می‌کند؟', 'رابط کاربری به شش زبان ارائه می‌شود: ترکی، انگلیسی، روسی، یونانی، فارسی و آلمانی.', 5, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('de', 'Was ist İşBul KKTC?', 'İşBul KKTC ist eine Job- und Karriereplattform für die Türkische Republik Nordzypern. Arbeitssuchende durchsuchen Anzeigen und bewerben sich; Arbeitgeber veröffentlichen Stellen und verwalten Bewerbungen.', 0, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('de', 'Welche Gebiete werden abgedeckt?', 'Die Plattform umfasst die sechs Bezirke Nordzyperns: Nikosia, Famagusta, Kyrenia, Morphou, Trikomo und Lefka.', 1, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('de', 'Kostet das Veröffentlichen oder Bewerben etwas?', 'Die Suche und die Bewerbung sind für Arbeitssuchende kostenlos. Arbeitgeber sehen sich Anzeigenpakete an; die Zahlung erfolgt nicht auf der Website — Bankdaten und Anweisungen werden nach Besprechung des Pakets privat per E-Mail oder WhatsApp mitgeteilt.', 2, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('de', 'Sind die Verzeichniseinträge geprüft?', 'Das Unternehmensverzeichnis macht Einträge aus bereitgestellten Quelldateien durchsuchbar; ein Eintrag bedeutet nicht, dass İşBul KKTC das Unternehmen geprüft hat.', 3, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('de', 'Wie kann ich İşBul KKTC kontaktieren?', 'Per E-Mail (info@isbulkktc.com), Telefon oder WhatsApp. Die Support-Kanäle sind im Footer der Website und auf der Kontaktseite aufgeführt.', 4, true);
insert into public.faq_entries (locale, question, answer, sort_order, is_published) values ('de', 'Welche Sprachen unterstützt die Plattform?', 'Die Oberfläche ist in sechs Sprachen verfügbar: Türkisch, Englisch, Russisch, Griechisch, Persisch und Deutsch.', 5, true);
insert into public.listing_plans (code, audience, name, blurb, features, color, listing_count, price_1, price_7, price_30, is_active, sort_order) values ('tek-ilan', 'TEK AÇIK POZİSYON', 'Tek İlan', 'Bir pozisyonu, ihtiyacınıza uygun 1, 7 veya 30 günlük süreyle yayımlamak için.', array['1 ilan hakkı', 'Her ilan için 1, 7 veya 30 gün', 'Tek bir açık pozisyon için'], '#4b8066', 1, 290, 690, 1290, true, 1);
